const createJobPosition=t=>{const e=(()=>{const t=Date.now(),e=Math.floor(1e3*Math.random());return parseInt(`${t.toString().slice(-6)}${e.toString().padStart(3,"0")}`)})(),r=t.title.toLowerCase().replace(/[^a-z0-9\s-]/g,"").replace(/\s+/g,"-").replace(/-+/g,"-").trim();const a=(new Date).toISOString();return{...t,id:e,slug:r,createdAt:a,updatedAt:a}},getStoredJobs=()=>{try{const t=localStorage.getItem("thinkred_job_positions");return t?JSON.parse(t):[]}catch(t){return[]}},saveJobsToStorage=t=>{try{localStorage.setItem("thinkred_job_positions",JSON.stringify(t))}catch(e){}},addJobPosition=t=>{const e=createJobPosition(t),r=[...getStoredJobs(),e];return saveJobsToStorage(r),e},deleteJobPosition=t=>{const e=getStoredJobs(),r=e.filter(e=>e.id!==t);return r.length!==e.length&&(saveJobsToStorage(r),!0)},getAllJobPositions=(t=[])=>[...t,...getStoredJobs()].sort((t,e)=>new Date(e.createdAt).getTime()-new Date(t.createdAt).getTime());export{addJobPosition as a,deleteJobPosition as d,getAllJobPositions as g};
